import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-plenitud-de-dios', 'C',
 [dict(t=1080, e=1145, titulo='La Palabra nos hace plenos', txt='Hoy a usted le va a caer la plenitud de Dios para su vida, para que cuando usted venga y empiece a trabajar en las cosas de Dios como deben ser, usted se sienta pleno. ¿Qué te da plenitud de abundancia? La Palabra de Dios. La Palabra de Dios nos hace plenos. La Palabra de Dios nos bendice, nos levanta, nos restaura; la Palabra de Dios te hace feliz. Tenemos la palabra profética más segura, que es la Biblia. […] Usted tiene la vida eterna en sus manos, la plenitud de Dios escrita para que se manifieste en su vida.'),
  dict(t=2481, e=2562, titulo='Una puerta que se llama Cristo', txt='Él le va a abrir una puerta que usted no ha visto, y esa puerta se llama Cristo, y vas a entrar, y ahí vas a tomar toda la abundancia que tiene Cristo, y con esa te vas a defender. Mire, a usted no le va a pasar igual que a los moradores de la tierra si está bajo cobertura. Si usted se sale, como Dina, que fue a ver una vueltecita, le van a dar tres vueltas. Y le quiero decir otra cosa: ya no hay tiempo para pecar. […] «Y os libraré de su esclavitud». Acuérdese que usted es esclavo de Cristo, no del mundo. «Y os redimiré». Hay redención para nosotros.'),
  dict(t=3691, e=3765, titulo='Antes de sanarlo, lo salvó', txt='[…] donde usted ponga las manos se salve la gente. No solo se sane: se salve. Acuérdese que al paralítico lo llevaron entre cuatro y lo subieron a la casa donde estaba Jesús. […] Pero el Señor, antes de sanarlo, ¿qué hizo? Lo salvó. Antes de sanarte, se salvó. Por eso, una de las oportunidades que tiene usted cuando habla con las personas es que le pregunte: ¿usted aceptó al Señor? No tiene nada que ver con lo que le voy a decir. Le voy a leer cuatro versículos que van a salvar su vida.')],
 [dict(t=1014, txt='Dios te quiere visitar esta noche para que tengas un alivio en tu vida. Él sabe cómo está tu vida.'),
  dict(t=3020, txt='¿No será que hoy Dios quiere que tu vida sea transparente? Que te metas con Dios como debe ser. Ya el tiempo se está acabando.'),
  dict(t=4518, txt='Plenitud de abundancia, hermano: te trae la Palabra y no te va a faltar nada.')],
 ['La Palabra de Dios nos hace plenos: ¿cuánto tiempo le das a ella esta semana y qué cambiaría si le dieras más?',
  'Cristo es la puerta que Dios abre y la cobertura que nos defiende: ¿en qué área te has salido de esa cobertura?',
  'Antes de sanar al paralítico, Jesús lo salvó: ¿a quién le preguntarías esta semana si ha aceptado al Señor?'],
 inicio=593)
